// Port of src/lib/csv/ukgLeave.ts.
// ─── UKG leave export parsing ────────────────────────────────────────────────
// Both leave exports arrive straight out of UKG's "Share → Export", which
// prefixes the real table with a metadata block:
//
//     Export Name:,Leave Liability-...
//     Generated By:,...
//     ...
//     (blank)
//     Location,Employee Name,Employee ID,Job,...     ← the real header row
//
// We find the header row by content rather than skipping a fixed count, so a
// future UKG release that adds or drops a preamble line can't silently shift
// every column.

using System.Text.RegularExpressions;
using Roster.Engine.Core;
using Roster.Engine.Leave;
using static Roster.Data.Feeds.CsvParse;

namespace Roster.Data.Feeds;

/// <param name="StoreCodes">Store codes seen in the file, for the "expected vs actual" upload note.</param>
/// <param name="Collapsed">Rows that exactly repeated another row and were kept once.</param>
public sealed record LeaveParseResult<T>(
    IReadOnlyList<T> Rows, IReadOnlyList<RowError> Errors, IReadOnlyList<string> StoreCodes, int? Collapsed = null);

public static class LiabilityHeaders
{
    public const string StoreCode = "StoreID";
    public const string Location = "Location";
    public const string EmployeeName = "Employee Name";
    public const string EmployeeId = "Employee ID";
    public const string Job = "Job";
    public const string Contract = "Contract Hrs";
    public const string Notional = "Notional Hrs";
    public const string Sick = "Sick Lve Accrued";
    public const string Annual = "Annual Lve Accrued";
    public const string Lieu = "Lieu Hrs Accrued";
    public const string Banked = "Banked Hrs Accrued";
    public const string Banked2 = "Banked 2 Hrs Accrued";
}

/// <summary>One employee's balances on the Leave Liability export.</summary>
/// <param name="Row">Line in the export, for error reports.</param>
/// <param name="RoleClass">Entitlement class: "SM", "ASM", "DSM", "SA" or "CASUAL".</param>
public sealed record ParsedLiabilityRow(
    int Row,
    string StoreCode,
    string? UkgLocation,
    string UkgEmployeeId,
    string EmployeeName,
    string? Job,
    string RoleClass,
    double ContractHours,
    double NotionalHours,
    double SickHours,
    double AnnualHours,
    double LieuHours,
    double BankedHours,
    double Banked2Hours) : IFeedRow;

public static class RequestHeaders
{
    public const string StoreCode = "StoreID";
    public const string EmployeeId = "Employee ID";
    public const string EmployeeName = "Employee Name";
    public const string LeaveType = "Leave Type";
    public const string StartDate = "Start Date";
    public const string EndDate = "End Date";
    public const string Status = "Status";
    public const string Approver = "Approver";
}

/// <summary>One booking on the Leave Request dataview.</summary>
/// <param name="Row">Line in the export, for error reports.</param>
public sealed record ParsedRequestRow(
    int Row,
    string StoreCode,
    string UkgEmployeeId,
    string EmployeeName,
    string LeaveType,
    DateOnly StartDate,
    DateOnly EndDate,
    string Status,
    string? Approver) : IFeedRow, IDedupableRequest;

public static partial class UkgLeave
{
    /// <summary>
    /// Strip UKG's preamble and parse the remainder. <paramref name="anchor"/> is a header that
    /// must appear in the real header row.
    /// </summary>
    public static ParsedCsv ParseUkgExport(string text, string anchor)
    {
        // text.split(/\r?\n/)
        var lines = text.Split('\n').Select(l => l.EndsWith('\r') ? l[..^1] : l).ToList();
        var wanted = JsText.ToLower(anchor);
        var start = 0;
        for (var i = 0; i < Math.Min(lines.Count, 40); i++)
        {
            var cells = lines[i].Split(',').Select(c => JsText.ToLower(StripQuotes(Js.Trim(c))));
            if (cells.Contains(wanted))
            {
                start = i;
                break;
            }
        }
        var body = string.Join("\n", lines.Skip(start));
        var result = Papa.Parse(body, new Papa.Config(
            TransformHeader: h =>
            {
                var t = Js.Trim(h);
                return t.StartsWith('﻿') ? t[1..] : t;
            },
            Transform: Js.Trim));
        return new ParsedCsv(result.Fields, result.Data);
    }

    // c.replace(/^"|"$/g, "")
    private static string StripQuotes(string c)
    {
        if (c.StartsWith('"')) c = c[1..];
        if (c.EndsWith('"')) c = c[..^1];
        return c;
    }

    /// <summary>
    /// UKG writes negatives in accounting brackets - "(69.48)" is −69.48. Blank is
    /// zero (a blank Banked column means no banked hours, not missing data).
    /// Anything else that is not a plain decimal - "N/A", "-", "1,5" - is NaN, for
    /// the caller to reject: sent on, it arrived in the database as an empty value
    /// and the column refused the file partway through writing it.
    /// </summary>
    public static double UkgNumber(string? raw)
    {
        var s = Js.Trim(raw ?? "");
        if (s.Length == 0) return 0;
        var neg = s.StartsWith('(') && s.EndsWith(')');
        var n = ParseDecimal(neg ? s[1..^1] : s);
        if (!double.IsFinite(n)) return double.NaN;
        return neg ? -n : n;
    }

    [GeneratedRegex(@"^([0-9]{1,2})-([0-9]{1,2})-([0-9]{4})\z")]
    private static partial Regex DashDate();

    /// <summary>
    /// UKG dates in the request export are "26-12-2026 12:00 AM" (DD-MM-YYYY with a
    /// midnight time). The shared ToIsoDate handles slashes and ISO; this adds the
    /// dash form and drops the time.
    /// </summary>
    public static string? UkgDate(string? raw)
    {
        var s = Js.Trim(raw ?? "");
        if (s.Length == 0) return null;
        var datePart = s.Split(' ')[0];
        var m = DashDate().Match(datePart);
        if (m.Success) return IsoDate(Int(m.Groups[3].Value), Int(m.Groups[2].Value), Int(m.Groups[1].Value));
        return ToIsoDate(datePart);
    }

    /// <summary>A cell by header (case-insensitive), "" when absent.</summary>
    internal static string Get(CsvRow row, string header) => Cell(row, header) ?? "";

    // ─── Liability export ────────────────────────────────────────────────────────

    public static LeaveParseResult<ParsedLiabilityRow> ParseLiability(string text)
    {
        var rows = ParseUkgExport(text, LiabilityHeaders.EmployeeName).Rows;
        var output = new List<ParsedLiabilityRow>();
        var errors = new List<RowError>();
        var codes = new HashSet<string>(StringComparer.Ordinal);

        // Every balance is checked, not only the contract: an unreadable Sick or
        // Banked cell used to pass and then stop the write halfway through.
        (string Key, string Header)[] figures =
        [
            ("contractHours", LiabilityHeaders.Contract),
            ("notionalHours", LiabilityHeaders.Notional),
            ("sickHours", LiabilityHeaders.Sick),
            ("annualHours", LiabilityHeaders.Annual),
            ("lieuHours", LiabilityHeaders.Lieu),
            ("bankedHours", LiabilityHeaders.Banked),
            ("banked2Hours", LiabilityHeaders.Banked2),
        ];

        for (var i = 0; i < rows.Count; i++)
        {
            var r = rows[i];
            var line = i + 2;
            var storeCode = JsText.ToUpper(Get(r, LiabilityHeaders.StoreCode));
            var name = Get(r, LiabilityHeaders.EmployeeName);
            var empId = Get(r, LiabilityHeaders.EmployeeId);
            if (name.Length == 0 && empId.Length == 0) continue; // trailing blank line
            if (storeCode.Length == 0)
            {
                errors.Add(new RowError(line, null, LiabilityHeaders.StoreCode, "Missing StoreID"));
                continue;
            }
            if (empId.Length == 0)
            {
                errors.Add(new RowError(line, storeCode, LiabilityHeaders.EmployeeId, "Missing Employee ID"));
                continue;
            }
            var jobCell = Get(r, LiabilityHeaders.Job);
            var job = jobCell.Length > 0 ? jobCell : null;
            // Job is authoritative; the name's rank prefix is the fallback when a
            // record has no job title.
            var roleClass = job is not null ? LeaveMetrics.RoleClassFromJob(job) : LeaveMetrics.RoleClassFromName(name);
            var values = figures.ToDictionary(f => f.Key, f => UkgNumber(Get(r, f.Header)), StringComparer.Ordinal);
            var unreadable = figures.Where(f => !double.IsFinite(values[f.Key])).Select(f => f.Header).FirstOrDefault();
            if (unreadable is not null)
            {
                errors.Add(new RowError(line, storeCode, unreadable, $"{unreadable} is not a number ('{Get(r, unreadable)}')"));
                continue;
            }
            codes.Add(storeCode);
            var location = Get(r, LiabilityHeaders.Location);
            output.Add(new ParsedLiabilityRow(
                Row: line,
                StoreCode: storeCode,
                UkgLocation: location.Length > 0 ? location : null,
                UkgEmployeeId: empId,
                EmployeeName: name,
                Job: job,
                RoleClass: roleClass,
                ContractHours: values["contractHours"],
                NotionalHours: values["notionalHours"],
                SickHours: values["sickHours"],
                AnnualHours: values["annualHours"],
                LieuHours: values["lieuHours"],
                BankedHours: values["bankedHours"],
                Banked2Hours: values["banked2Hours"]));
        }

        // One balance per employee per store: two different rows for the same
        // person would land in one write and the database refuses the whole file.
        var dupes = Duplicates.CheckDuplicates(
            output,
            r => $"{r.StoreCode}|{r.UkgEmployeeId}",
            r => $"Employee ID {r.UkgEmployeeId} at {r.StoreCode}",
            LiabilityHeaders.EmployeeId);
        return new LeaveParseResult<ParsedLiabilityRow>(
            dupes.Rows,
            Duplicates.ByRow([.. errors, .. dupes.Errors.Select(e => e with { Field = LiabilityHeaders.EmployeeId })]),
            Js.SortDefault([.. codes]),
            dupes.Collapsed);
    }

    // ─── Request export ──────────────────────────────────────────────────────────

    public static LeaveParseResult<ParsedRequestRow> ParseLeaveRequests(string text)
    {
        var rows = ParseUkgExport(text, RequestHeaders.LeaveType).Rows;
        var output = new List<ParsedRequestRow>();
        var errors = new List<RowError>();
        var codes = new HashSet<string>(StringComparer.Ordinal);

        for (var i = 0; i < rows.Count; i++)
        {
            var r = rows[i];
            var line = i + 2;
            var storeCode = JsText.ToUpper(Get(r, RequestHeaders.StoreCode));
            var empId = Get(r, RequestHeaders.EmployeeId);
            var type = Get(r, RequestHeaders.LeaveType);
            if (empId.Length == 0 && type.Length == 0) continue;
            if (storeCode.Length == 0)
            {
                errors.Add(new RowError(line, null, RequestHeaders.StoreCode, "Missing StoreID"));
                continue;
            }
            // A booking without an employee is nobody's leave - and two of them on the
            // same dates collapsed into one, so one person's leave disappeared.
            if (empId.Length == 0)
            {
                errors.Add(new RowError(line, storeCode, RequestHeaders.EmployeeId, "Missing Employee ID"));
                continue;
            }
            var start = UkgDate(Get(r, RequestHeaders.StartDate));
            var end = UkgDate(Get(r, RequestHeaders.EndDate));
            if (start is null || end is null)
            {
                errors.Add(new RowError(
                    line, storeCode, start is not null ? RequestHeaders.EndDate : RequestHeaders.StartDate,
                    "Unparseable or impossible date (expected DD-MM-YYYY)"));
                continue;
            }
            if (string.CompareOrdinal(end, start) < 0)
            {
                errors.Add(new RowError(line, storeCode, RequestHeaders.EndDate, "End Date is before Start Date"));
                continue;
            }
            codes.Add(storeCode);
            var approver = Get(r, RequestHeaders.Approver);
            output.Add(new ParsedRequestRow(
                Row: line,
                StoreCode: storeCode,
                UkgEmployeeId: empId,
                EmployeeName: Get(r, RequestHeaders.EmployeeName),
                LeaveType: type,
                StartDate: Date(start),
                EndDate: Date(end),
                Status: Get(r, RequestHeaders.Status),
                Approver: approver.Length > 0 ? approver : null));
        }

        return new LeaveParseResult<ParsedRequestRow>(output, errors, Js.SortDefault([.. codes]));
    }
}
